[CmdletBinding()]
param([string]$StateDirectory='C:\CodexRuntime\operator\admin\skincos\observability',[string]$DashboardTaskName='SkincosObservabilityDashboard')
$ErrorActionPreference='Stop'; $healthPath=Join-Path $StateDirectory 'monitor-health.json'; $stale=$true; if(Test-Path $healthPath){try{$health=Get-Content -Raw $healthPath|ConvertFrom-Json;$stale=([DateTime]::UtcNow-[DateTime]::Parse($health.last_success_at).ToUniversalTime()).TotalSeconds -gt 180}catch{}}
if($stale){$message='SKINCOS ALERT: external monitor is stale; watchdog is restarting the local dashboard.';try{Write-EventLog -LogName Application -Source 'SkincosObservability' -EventId 1003 -EntryType Warning -Message $message}catch{};try{& "$env:SystemRoot\System32\msg.exe" * /TIME:120 $message|Out-Null}catch{};[System.IO.File]::WriteAllText((Join-Path $StateDirectory 'watchdog-alert.json'),(@{ok=$false;observed_at=[DateTime]::UtcNow.ToString('o');reason='monitor-stale'}|ConvertTo-Json))}
$task=Get-ScheduledTask -TaskName $DashboardTaskName -ErrorAction Stop; if($task.State -ne 'Running'){Start-ScheduledTask -TaskName $DashboardTaskName}
